import fs from 'node:fs/promises';import assert from 'node:assert/strict';import test from 'node:test';
import {isSpeechEntry,prepareSpeechEntry,serveSpeechEnquiry,ENQUIRY_PATH,ENQUIRY_BUNDLE} from '../deployment/speech-enquiry-handler.mjs';
import {serveSpeech} from '../deployment/speech-handler.mjs';
const base='https://www.pinnacleblooms.org';
const original=await fs.readFile('scripts/fixtures/speech-enquiry.html','utf8');
test('entry guard never rewrites untagged, ambiguous, private or non-GET requests',()=>{for(const suffix of ['', '?entry=other','?entry=speech-assessment&entry=other'])assert(!isSpeechEntry(new Request(base+ENQUIRY_PATH+suffix)));for(const options of [{method:'POST'},{method:'HEAD'},{headers:{authorization:'fixture'}},{headers:{range:'bytes=0-1'}},{headers:{'cache-control':'no-transform'}}])assert(!isSpeechEntry(new Request(base+ENQUIRY_PATH+'?entry=speech-assessment',options)));assert(isSpeechEntry(new Request(base+ENQUIRY_PATH+'?entry=speech-assessment')));});
test('known page preserves form and functional script, excludes analytics and legacy offer markup',()=>{const h=prepareSpeechEntry(original);assert(h.includes(ENQUIRY_BUNDLE));assert(h.includes('jquery'));assert(h.includes('contact-form-title'));assert(!h.includes('application/ld+json'));assert(!/<script[^>]*[\s\S]*?(?:googletagmanager|cloudflareinsights)/.test(h));});
test('unknown origin is returned unchanged including validators',async()=>{const origin=new Response('unknown contract',{headers:{'content-type':'text/html','etag':'"origin"'}});const result=await serveSpeechEnquiry(new Request(base+ENQUIRY_PATH+'?entry=speech-assessment'),{},async()=>origin);assert.equal(result,origin);assert.equal(await result.text(),'unknown contract');});
test('both guide routes and aliases serve only their exact assets',async()=>{for(const name of ['first-visit-guide','teacher-observation-guide']){const key='/pinnacle-pages-html/'+name+'.html',inv={[key]:'fixture'},env={ASSETS:{fetch:async r=>{assert.equal(new URL(r.url).pathname,key);return new Response('guide')}}};const r=await serveSpeech(new Request(base+'/speech-therapy/'+name),env,inv);assert.equal(await r.text(),'guide');for(const suffix of ['/', '.html']){const a=await serveSpeech(new Request(base+'/speech-therapy/'+name+suffix+'?test=1'),env,inv);assert.equal(a.status,301);assert.equal(a.headers.get('location'),base+'/speech-therapy/'+name+'?test=1');}}});
